/**
 * Source report specs (generated by scripts/extract-report-specs.mjs into public/source-intelligence/report-specs.json):
 * the exact filter list, options, defaults and onload buttons each report's source .js defines, plus the report JSON
 * header (ref_doctype, documentation_url, default_print_format, prepared_report, roles…).
 *
 * Dynamic defaults are recorded as "@@<expression>" tokens and resolved here over the virtual store with the same
 * meaning frappe gives them (frappe.defaults.* through the shared Session Defaults resolver, frappe.datetime.*,
 * erpnext.utils.get_fiscal_year, locals[":DocType"][name].field). An expression without a port resolves to
 * undefined — the filter starts empty rather than with an invented value.
 */
import { queryOptions } from "@tanstack/react-query";
import { adapter } from "./adapter";
import { defaultCompany, getUserDefault, globalDefault } from "./sessionDefaults";
import { customDimensions } from "./dimensions";
import type { ReportEntry } from "./catalog";

export interface SpecOption { value: string; label: string }
export interface SpecFilter {
  fieldname?: string | undefined; label?: string | undefined; fieldtype?: string | undefined; options?: unknown; default?: unknown; reqd?: number | boolean | undefined;
  hidden?: number | boolean | undefined; depends_on?: string | undefined; mandatory_depends_on?: string | undefined; read_only?: number | undefined; width?: string | number | undefined;
  on_change?: boolean | undefined; get_data?: boolean | undefined; get_query?: unknown; description?: string | undefined; wildcard_filter?: number | undefined;
}
export interface ReportSpec {
  app: string; report_type: string; ref_doctype: string | null; module: string; is_standard: string; add_total_row: number;
  prepared_report: number; documentation_url: string | null; default_print_format: string | null; letter_head: string | null;
  roles: string[]; source_json: string; source_js: string | null; filters: SpecFilter[]; add_dimensions_at: number | null;
  onload_actions: { kind: string; label: string; group?: string }[]; has_formatter: boolean; tree: boolean;
  name_field: string | null; parent_field: string | null; initial_depth: number | null;
  collapsible_filters: boolean; separate_check_filters: boolean; eval_error: string | null;
}
export interface ReportSpecFile { generated_by: string; summary: Record<string, number>; reports: Record<string, ReportSpec> }

const isB = typeof window !== "undefined";
export const reportSpecsQuery = queryOptions({
  queryKey: ["report-specs"],
  queryFn: async (): Promise<ReportSpecFile> => { const r = await fetch("/source-intelligence/report-specs.json"); if (!r.ok) throw new Error("report-specs.json missing"); return r.json(); },
  staleTime: Infinity, enabled: isB,
});

// ---------------- token expressions ----------------
type Tok = { t: "str" | "num" | "id" | "punct"; v: string };
function lex(s: string): Tok[] {
  const out: Tok[] = []; let i = 0;
  while (i < s.length) {
    const c = s[i]!;
    if (c === "@" && s[i + 1] === "@") { i += 2; continue; }
    if (c === '"') { let j = i + 1, v = ""; while (j < s.length && s[j] !== '"') { if (s[j] === "\\") j++; v += s[j] ?? ""; j++; } out.push({ t: "str", v }); i = j + 1; continue; }
    if (/\d/.test(c) || (c === "-" && /\d/.test(s[i + 1] ?? ""))) { const m = s.slice(i).match(/^-?\d+(\.\d+)?/)!; out.push({ t: "num", v: m[0] }); i += m[0].length; continue; }
    if (/[A-Za-z_$:]/.test(c)) { const m = s.slice(i).match(/^[A-Za-z_$:][\w$:]*/)!; out.push({ t: "id", v: m[0] }); i += m[0].length; continue; }
    out.push({ t: "punct", v: c }); i++;
  }
  return out;
}
type Node =
  | { k: "lit"; v: unknown }
  | { k: "path"; path: string }
  | { k: "call"; callee: string; args: Node[] }
  | { k: "index"; obj: Node; key: Node }
  | { k: "member"; obj: Node; name: string };
/** expr := atom ( "." id | "[" expr "]" | "(" args ")" )* ; atom := str | num | true/false | id */
function parse(toks: Tok[]): Node | undefined {
  let p = 0;
  const expr = (): Node | undefined => {
    const a = toks[p]; if (!a) return undefined;
    let node: Node;
    if (a.t === "str") { p++; node = { k: "lit", v: a.v }; }
    else if (a.t === "num") { p++; node = { k: "lit", v: Number(a.v) }; }
    else if (a.t === "id" && (a.v === "true" || a.v === "false")) { p++; node = { k: "lit", v: a.v === "true" }; }
    else if (a.t === "id") { p++; node = { k: "path", path: a.v }; }
    else return undefined;
    for (;;) {
      const t = toks[p];
      if (t?.t === "punct" && t.v === "." && toks[p + 1]?.t === "id") { const name = toks[p + 1]!.v; node = node.k === "path" ? { k: "path", path: `${node.path}.${name}` } : { k: "member", obj: node, name }; p += 2; continue; }
      if (t?.t === "punct" && t.v === "(") {
        p++; const args: Node[] = [];
        while (toks[p] && !(toks[p]!.t === "punct" && toks[p]!.v === ")")) { const e = expr(); if (e) args.push(e); if (toks[p]?.v === ",") p++; else if (!e) p++; }
        p++; node = { k: "call", callee: node.k === "path" ? node.path : "?", args }; continue;
      }
      if (t?.t === "punct" && t.v === "[") { p++; const key = expr(); p++; node = { k: "index", obj: node, key: key ?? { k: "lit", v: undefined } }; continue; }
      break;
    }
    return node;
  };
  return expr();
}

const today = () => new Date().toISOString().slice(0, 10);
const iso = (d: Date) => d.toISOString().slice(0, 10);
function addMonths(date: string, n: number): string { const d = new Date(`${date}T00:00:00Z`); const day = d.getUTCDate(); d.setUTCDate(1); d.setUTCMonth(d.getUTCMonth() + n); const last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate(); d.setUTCDate(Math.min(day, last)); return iso(d); }
function addDays(date: string, n: number): string { const d = new Date(`${date}T00:00:00Z`); d.setUTCDate(d.getUTCDate() + n); return iso(d); }
/** erpnext.utils.get_fiscal_year(date, with_dates): [name, year_start_date, year_end_date] of the Fiscal Year covering date. */
export function fiscalYearFor(date: string): [string, string, string] | undefined {
  const fy = adapter.list("Fiscal Year").filter((y) => !Number(y["disabled"] ?? 0)).find((y) => String(y["year_start_date"]) <= date && String(y["year_end_date"]) >= date);
  return fy ? [fy.name, String(fy["year_start_date"]), String(fy["year_end_date"])] : undefined;
}

type Doc = Record<string, unknown>;
const LOCAL_DOC = Symbol("local-doc");
function evalNode(n: Node | undefined): unknown {
  if (!n) return undefined;
  if (n.k === "lit") return typeof n.v === "string" && n.v.startsWith("@@") ? resolveSpecValue(n.v) : n.v;
  if (n.k === "path") return undefined;
  if (n.k === "index") {
    const key = evalNode(n.key);
    if (n.obj.k === "path" && n.obj.path.startsWith("locals.:")) { const dt = n.obj.path.slice("locals.:".length); const d = key ? adapter.get(dt, String(key)) : undefined; return d ? { [LOCAL_DOC]: d } : undefined; }
    const obj = evalNode(n.obj);
    return Array.isArray(obj) ? obj[Number(key)] : undefined;
  }
  if (n.k === "member") {
    const obj = evalNode(n.obj) as { [LOCAL_DOC]?: Doc } | undefined;
    const v = obj?.[LOCAL_DOC]?.[n.name];
    return v === undefined || v === null || v === "" ? undefined : v;
  }
  const a = (i: number) => evalNode(n.args[i]);
  const s = (i: number) => { const v = a(i); return v === undefined || v === null ? undefined : String(v); };
  switch (n.callee) {
    // defaults.js get_user_default / get_default: session → global default, never a value outside the user's User
    // Permissions (in_user_permission); Company keeps the preview's permitted-company fallback (defaultCompany)
    case "frappe.defaults.get_user_default": case "frappe.defaults.get_default": { const k = s(0); return k ? (/^company$/i.test(k) ? defaultCompany() || undefined : getUserDefault(k)) ?? fyDefault(k) : undefined; }
    case "frappe.defaults.get_global_default": { const k = s(0); return k ? globalDefault(k) ?? fyDefault(k) : undefined; }
    case "frappe.datetime.get_today": case "frappe.datetime.nowdate": case "frappe.datetime.now_date": return today();
    case "frappe.datetime.now_datetime": return `${today()} ${new Date().toISOString().slice(11, 19)}`;
    case "frappe.datetime.get_time": case "frappe.datetime.now_time": return new Date().toISOString().slice(11, 19);
    case "frappe.datetime.add_months": { const d = s(0), m = Number(a(1)); return d && Number.isFinite(m) ? addMonths(d.slice(0, 10), m) : undefined; }
    case "frappe.datetime.add_days": { const d = s(0), m = Number(a(1)); return d && Number.isFinite(m) ? addDays(d.slice(0, 10), m) : undefined; }
    case "frappe.datetime.month_start": return `${today().slice(0, 7)}-01`;
    case "frappe.datetime.month_end": return addDays(addMonths(`${today().slice(0, 7)}-01`, 1), -1);
    case "frappe.datetime.year_start": return `${today().slice(0, 4)}-01-01`;
    case "frappe.datetime.year_end": return `${today().slice(0, 4)}-12-31`;
    case "frappe.datetime.convert_to_system_tz": case "frappe.datetime.obj_to_str": return a(0);
    // get_fiscal_year(date) → name; get_fiscal_year(date, true) → [name, start, end] (indexed by the caller)
    case "erpnext.utils.get_fiscal_year": { const d = s(0); const fy = d ? fiscalYearFor(d.slice(0, 10)) : undefined; return a(1) === true ? fy : fy?.[0]; }
    case "erpnext.get_currency": { const c = s(0); return c ? (adapter.get("Company", c)?.["default_currency"] as string | undefined) : undefined; }
    case "erpnext.get_presentation_currency_list": return presentationCurrencies();
  }
  return undefined;
}
/** Fiscal-year keys frappe keeps in user defaults (year_start_date / year_end_date / fiscal_year) on a site. */
function fyDefault(key: string): string | undefined {
  const fy = fiscalYearFor(today()); if (!fy) return undefined;
  return key === "year_start_date" ? fy[1] : key === "year_end_date" ? fy[2] : key === "fiscal_year" ? fy[0] : undefined;
}
/** erpnext.get_presentation_currency_list: "" + every enabled currency in boot docs. */
export function presentationCurrencies(): string[] {
  const used = new Set(adapter.list("Company").map((c) => String(c["default_currency"] ?? "")).filter(Boolean));
  const enabled = adapter.list("Currency").filter((c) => Number(c["enabled"] ?? 0) === 1).map((c) => c.name);
  return ["", ...[...new Set([...used, ...enabled])].sort()];
}

/** Resolve a spec value: literals pass through, "@@…" tokens are evaluated, unknown expressions give undefined. */
export function resolveSpecValue(v: unknown): unknown {
  if (typeof v !== "string" || !v.startsWith("@@")) return v;
  try {
    const out = evalNode(parse(lex(v)));
    return out && typeof out === "object" && !Array.isArray(out) ? undefined : out;
  } catch { return undefined; }
}
export const isToken = (v: unknown): v is string => typeof v === "string" && v.startsWith("@@");

/** Select options in source form: "a\nb" string, ["a","b"], [{value,label}] or a token (presentation currencies). */
export function specOptions(f: SpecFilter): SpecOption[] {
  let o: unknown = f.options;
  if (isToken(o)) o = resolveSpecValue(o);
  if (typeof o === "string") return f.fieldtype === "Select" || f.fieldtype === "Autocomplete" ? o.split("\n").map((x) => ({ value: x, label: x })) : [];
  if (Array.isArray(o)) return o.flatMap((x) => (typeof x === "string" ? [{ value: x, label: x }] : x && typeof x === "object" && "value" in x ? [{ value: String((x as { value: unknown }).value ?? ""), label: String((x as { label?: unknown }).label ?? (x as { value: unknown }).value ?? "") }] : []));
  return [];
}
/** Link / MultiSelectList target DocType (options string naming a DocType). MultiSelectList on a Dynamic field names the discriminator filter. */
export function specLinkTarget(f: SpecFilter): string | undefined {
  return (f.fieldtype === "Link" || f.fieldtype === "MultiSelectList" || f.fieldtype === "Dynamic Link") && typeof f.options === "string" && !isToken(f.options) ? f.options : undefined;
}

/** Default filter value as the workbench stores it (string; Check "1"/""; MultiSelectList JSON array). */
export function specDefault(f: SpecFilter): string {
  const v = resolveSpecValue(f.default);
  if (v === undefined || v === null || v === "") return "";
  if (f.fieldtype === "Check") return Number(v) ? "1" : "";
  if (f.fieldtype === "MultiSelectList") return JSON.stringify(Array.isArray(v) ? v.map(String) : [String(v)]);
  if (Array.isArray(v)) return String(v[0] ?? "");
  return String(v);
}
/** frappe MultiSelectList value: JSON array (or a single plain value / comma list typed by hand). */
export function multiValues(v: string | undefined): string[] {
  if (!v) return [];
  if (v.startsWith("[")) { try { const a = JSON.parse(v) as unknown; return Array.isArray(a) ? a.map(String).filter(Boolean) : []; } catch { return []; } }
  return v.split(",").map((x) => x.trim()).filter(Boolean);
}

/** A source filter as the report workbench renders it; `applied` = the local runner reads it (else server-only). */
export interface WbFilter extends SpecFilter { fieldname: string; applied: boolean; single?: boolean | undefined }

/**
 * Source filters merged with what the local runner applies: source order, labels, types and options win; a filter
 * the runner does not read is shown locked (server-only); runner-only filters follow; accounting dimensions are
 * inserted where erpnext.utils.add_dimensions puts them (MultiSelectList, label = dimension DocType).
 */
export function workbenchFilters(spec: ReportSpec | undefined, entry: ReportEntry | undefined, runnerFilters: { fieldname: string; fieldtype: string; label: string; options?: string | string[] | undefined }[] | undefined): WbFilter[] {
  const runnerBy = new Map((runnerFilters ?? []).map((f) => [f.fieldname, f]));
  let list: SpecFilter[] = spec?.filters?.length ? [...spec.filters] : (runnerFilters ?? entry?.filters ?? []).map((f) => ({ fieldname: f.fieldname, label: f.label, fieldtype: f.fieldtype, options: f.options, reqd: (f as { reqd?: boolean }).reqd ? 1 : 0 }));
  if (spec?.add_dimensions_at !== null && spec?.add_dimensions_at !== undefined) {
    // erpnext.utils.add_dimensions → get_dimensions(with_cost_center_and_project=False): configured dimensions only
    const dims = customDimensions().filter((d) => !list.some((x) => x.fieldname === d.fieldname)).map((d) => ({ fieldname: d.fieldname, label: d.document_type, fieldtype: "MultiSelectList", options: d.document_type }));
    list = [...list.slice(0, spec.add_dimensions_at), ...dims, ...list.slice(spec.add_dimensions_at)];
  }
  const out: WbFilter[] = list.map((f, i) => {
    const fieldname = f.fieldname ?? `__break_${i}`;
    const rf = runnerBy.get(fieldname);
    const applied = !runnerFilters || !!rf;
    return { ...f, fieldname, applied, single: f.fieldtype === "MultiSelectList" && !!rf && rf.fieldtype !== "MultiSelectList" };
  });
  if (runnerFilters) for (const rf of runnerFilters) if (!out.some((f) => f.fieldname === rf.fieldname)) out.push({ fieldname: rf.fieldname, label: rf.label, fieldtype: rf.fieldtype, options: rf.options, applied: true });
  return out;
}

